## 4. View Controller 2: Catalog Views Controller (`app/js/views/catalog.js`)

### 4.1 Responsibilities
1. Powers both `#view-movies` (`mediaType: 'movie'`) and `#view-series` (`mediaType: 'tv'`).
2. Fetches dynamic genre taxonomies from TMDB (`TmdbClient.getGenres(mediaType)`), generating filter pills.
3. Implements 2D 6-column grid (`.content-grid-6col`) compliant with the 1080p canvas and 5% TV-safe margins.
4. Manages state: `activeGenreId`, `activeSortBy`, `activeYear`, `currentPage`, `totalPages`, `isLoading`.
5. Seamless pagination ("Load More"): Appends 20 additional cards without clearing existing DOM or interrupting user focus.

### 4.2 6-Column 2D Grid Specification
- **Canvas Resolution**: `1920 × 1080 px`
- **Safe Margins**: `padding-left: 96px`, `padding-right: 96px` (Usable width = 1728px).
- **Grid Configuration**:
  - `display: grid; grid-template-columns: repeat(6, 1fr);`
  - `column-gap: 24px; row-gap: 28px;`
  - Individual card column width: `(1728 - (5 * 24)) / 6 = 1608 / 6 = 268px` (or `flex: 0 0 220px` centered).
  - Matches `tokens.css` `--card-poster-width: 220px`.
- **Directional D-Pad Alignment**:
  - Exact column indexing ensures `ArrowDown` transitions from item `i` to item `i + 6`.
  - Geometric scoring in `navigation.js` gives perpendicular overlap bonus to vertically aligned items.

```
Row 1: [ Card 0 ]  [ Card 1 ]  [ Card 2 ]  [ Card 3 ]  [ Card 4 ]  [ Card 5 ]
            │            │            │            │            │            │  (ArrowDown)
            ▼            ▼            ▼            ▼            ▼            ▼
Row 2: [ Card 6 ]  [ Card 7 ]  [ Card 8 ]  [ Card 9 ]  [ Card 10]  [ Card 11]
```

### 4.3 Complete Catalog Controller Specification
```javascript
(function (global) {
  'use strict';

  function CatalogViewController(viewId, mediaType) {
    this.viewId = viewId;
    this.mediaType = mediaType; // 'movie' or 'tv'
    this.container = null;
    this.gridContainer = null;
    this.filterBar = null;

    this.state = {
      activeGenreId: null,
      activeSortBy: 'popularity.desc',
      activeYear: null,
      currentPage: 1,
      totalPages: 1,
      isLoading: false,
      items: []
    };
  }

  CatalogViewController.prototype.init = function () {
    this.container = document.getElementById(this.viewId);
    if (!this.container) return;

    this.gridContainer = this.container.querySelector('.content-grid-6col');
    this.filterBar = this.container.querySelector('.filter-bar');
    this.bindFilters();
  };

  CatalogViewController.prototype.bindFilters = function () {
    var self = this;
    if (!this.filterBar) return;

    this.filterBar.addEventListener('click', function (e) {
      var pill = e.target.closest('.filter-pill');
      if (!pill) return;

      var genreId = pill.getAttribute('data-genre-id');
      self.state.activeGenreId = genreId ? parseInt(genreId, 10) : null;

      // Update active styling
      var allPills = self.filterBar.querySelectorAll('.filter-pill');
      allPills.forEach(function (p) { p.classList.remove('active'); });
      pill.classList.add('active');

      // Reset and reload catalog
      self.state.currentPage = 1;
      self.state.items = [];
      self.loadCatalog(true);
    });
  };

  CatalogViewController.prototype.activate = function () {
    this.init();
    if (this.state.items.length === 0) {
      this.loadGenres();
      this.loadCatalog(true);
    }
  };

  CatalogViewController.prototype.loadGenres = function () {
    var self = this;
    if (!window.TmdbClient || !this.filterBar) return;

    window.TmdbClient.getGenres(this.mediaType).then(function (genres) {
      if (!genres || !genres.length) return;

      var fragment = document.createDocumentFragment();
      var defaultPill = document.createElement('button');
      defaultPill.className = 'filter-pill active';
      defaultPill.setAttribute('data-nav', 'true');
      defaultPill.setAttribute('data-nav-group', self.mediaType + '-filter');
      defaultPill.setAttribute('data-nav-default', 'true');
      defaultPill.textContent = self.mediaType === 'tv' ? 'All Shows' : 'All Movies';
      fragment.appendChild(defaultPill);

      // Render top 9 genres
      var topGenres = genres.slice(0, 9);
      for (var i = 0; i < topGenres.length; i++) {
        var pill = document.createElement('button');
        pill.className = 'filter-pill';
        pill.setAttribute('data-nav', 'true');
        pill.setAttribute('data-nav-group', self.mediaType + '-filter');
        pill.setAttribute('data-genre-id', String(topGenres[i].id));
        pill.textContent = topGenres[i].name;
        fragment.appendChild(pill);
      }

      self.filterBar.innerHTML = '';
      self.filterBar.appendChild(fragment);
    });
  };

  CatalogViewController.prototype.loadCatalog = function (reset) {
    var self = this;
    if (this.state.isLoading || !window.TmdbClient) return;

    this.state.isLoading = true;
    var params = {
      page: this.state.currentPage,
      genreId: this.state.activeGenreId,
      sortBy: this.state.activeSortBy,
      year: this.state.activeYear
    };

    window.TmdbClient.discover(this.mediaType, params).then(function (res) {
      self.state.isLoading = false;
      if (!res || !res.results) return;

      self.state.totalPages = res.total_pages || 1;
      var newItems = res.results;

      if (reset) {
        self.state.items = newItems;
        self.renderGrid(newItems, true);
      } else {
        self.state.items = self.state.items.concat(newItems);
        self.renderGrid(newItems, false);
      }
    }).catch(function (err) {
      self.state.isLoading = false;
      console.error('[CatalogViewController] Discover failed:', err);
    });
  };

  CatalogViewController.prototype.loadMore = function () {
    if (this.state.currentPage < this.state.totalPages && !this.state.isLoading) {
      this.state.currentPage++;
      this.loadCatalog(false);
    }
  };

  CatalogViewController.prototype.renderGrid = function (items, isReset) {
    if (!this.gridContainer) return;

    var fragment = document.createDocumentFragment();
    var startIndex = isReset ? 0 : (this.state.items.length - items.length);

    for (var i = 0; i < items.length; i++) {
      var card = CardFactory.createPosterCard(items[i], this.mediaType + '-grid', startIndex + i, {
        mediaType: this.mediaType
      });
      fragment.appendChild(card);
    }

    if (isReset) {
      this.gridContainer.innerHTML = '';
    }
    this.gridContainer.appendChild(fragment);
  };

  global.CatalogViewController = CatalogViewController;
  global.MoviesViewController = new CatalogViewController('view-movies', 'movie');
  global.SeriesViewController = new CatalogViewController('view-series', 'tv');
})(typeof window !== 'undefined' ? window : this);
```

