## 5. View Controller 3: Search View Controller & Virtual Keyboard (`app/js/views/search.js`)

### 5.1 Responsibilities
1. Houses the On-Screen TV D-Pad Virtual Keyboard (Numbers, QWERTY letters, and action keys).
2. Manages Modal Focus Trapping (`SpatialNav.trap` / `SpatialNav.untrap`) to constrain navigation within the keyboard while typing and permit smooth escape to search results.
3. Displays live accumulated search query with blinking cursor.
4. Executes 300ms debounced live multi-search queries via `TmdbClient.searchMulti(query, page)`.
5. Renders live search results in a 6-column grid with item count, empty state, and error handling.
6. Maps webOS remote color keys (Red = Clear, Green = Space, Yellow/Blue = Focus Results).

### 5.2 Virtual Keyboard Geometry & Grid Layout
```
+---------------------------------------------------------------------------------------------------+
|  Row 1 (Numbers) : [ 1 ] [ 2 ] [ 3 ] [ 4 ] [ 5 ] [ 6 ] [ 7 ] [ 8 ] [ 9 ] [ 0 ]                   |
|  Row 2 (Q - P)   : [ Q ] [ W ] [ E ] [ R ] [ T ] [ Y ] [ U ] [ I ] [ O ] [ P ]                   |
|  Row 3 (A - L)   :   [ A ] [ S ] [ D ] [ F ] [ G ] [ H ] [ J ] [ K ] [ L ]                       |
|  Row 4 (Z - M)   :     [ Z ] [ X ] [ C ] [ V ] [ B ] [ N ] [ M ]                                 |
|  Row 5 (Actions) : [      SPACE (w: 360px)      ] [ ⌫ DELETE (w: 220px) ] [ CLEAR (w: 180px) ]  |
+---------------------------------------------------------------------------------------------------+
```

### 5.3 Modal Focus Trapping Protocol
1. **Engaging the Trap**: When `#view-search` is active and focus enters the virtual keyboard, `SpatialNav.trap('.tv-keyboard-container')` is called.
2. **Containment**: D-pad navigation (`ArrowUp`, `ArrowDown`, `ArrowLeft`, `ArrowRight`) is strictly restricted to keyboard keys. `ArrowUp` from Row 1 cannot escape to the header.
3. **Escaping to Results**:
   - Pressing `ArrowDown` while on Row 5 action keys triggers an untrap event:
     `SpatialNav.untrap()`, followed immediately by `SpatialNav.setFocus(firstResultCard)`.
   - Alternatively, pressing webOS Yellow or Blue color keys releases the trap and shifts focus to the first search result.
4. **Returning to Keyboard**:
   - Pressing `ArrowUp` while on the first row of search results or pressing `Back` releases focus from the grid, focuses the `SPACE` key on the keyboard, and re-engages `SpatialNav.trap('.tv-keyboard-container')`.

### 5.4 Complete Search Controller Specification
```javascript
(function (global) {
  'use strict';

  var SearchViewController = {
    initialized: false,
    query: '',
    debounceTimer: null,
    isTrapped: false,

    init: function () {
      if (this.initialized) return;
      this.initialized = true;

      this.container = document.getElementById('view-search');
      this.inputDisplay = document.getElementById('search-query-text');
      this.placeholder = document.getElementById('search-query-placeholder');
      this.resultsGrid = document.getElementById('search-results-grid');
      this.resultsCount = document.getElementById('search-results-count');
      this.keyboard = this.container.querySelector('.tv-keyboard-container');

      this.bindKeyboard();
    },

    bindKeyboard: function () {
      var self = this;
      if (!this.keyboard) return;

      this.keyboard.addEventListener('click', function (e) {
        var keyBtn = e.target.closest('.key-btn');
        if (!keyBtn) return;

        var keyVal = keyBtn.getAttribute('data-key');
        if (keyVal === 'BACKSPACE') {
          self.query = self.query.slice(0, -1);
        } else if (keyVal === 'CLEAR') {
          self.query = '';
        } else if (keyVal === 'SPACE') {
          self.query += ' ';
        } else if (keyVal) {
          self.query += keyVal;
        }

        self.updateInputDisplay();
        self.scheduleSearch();
      });

      // Down navigation from bottom row (Row 5) escapes to search results
      if (window.SpatialNav) {
        window.SpatialNav.on('deadend', function (data) {
          if (window.CinejoyApp && window.CinejoyApp.state.currentView === 'search') {
            if (data.direction === 'down' && data.element && data.element.closest('.tv-keyboard-container')) {
              self.jumpToResults();
            }
          }
        });
      }
    },

    activate: function () {
      this.init();
      this.engageTrap();
      if (!this.query) {
        var firstKey = this.keyboard.querySelector('[data-key="Q"]') || this.keyboard.querySelector('.key-btn');
        if (firstKey && window.SpatialNav) {
          window.SpatialNav.setFocus(firstKey);
        }
      }
    },

    deactivate: function () {
      this.releaseTrap();
      if (this.debounceTimer) {
        clearTimeout(this.debounceTimer);
        this.debounceTimer = null;
      }
    },

    engageTrap: function () {
      if (window.SpatialNav && this.keyboard) {
        window.SpatialNav.trap(this.keyboard);
        this.isTrapped = true;
      }
    },

    releaseTrap: function () {
      if (window.SpatialNav && this.isTrapped) {
        window.SpatialNav.untrap();
        this.isTrapped = false;
      }
    },

    jumpToResults: function () {
      if (!this.resultsGrid) return;
      var firstCard = this.resultsGrid.querySelector('.card-poster[data-nav="true"]');
      if (firstCard && window.SpatialNav) {
        this.releaseTrap();
        window.SpatialNav.setFocus(firstCard);
      }
    },

    updateInputDisplay: function () {
      if (this.inputDisplay) {
        this.inputDisplay.textContent = this.query;
      }
      if (this.placeholder) {
        this.placeholder.style.display = this.query.length > 0 ? 'none' : 'inline';
      }
    },

    scheduleSearch: function () {
      var self = this;
      if (this.debounceTimer) {
        clearTimeout(this.debounceTimer);
      }

      if (!this.query.trim()) {
        this.renderResults([]);
        if (this.resultsCount) this.resultsCount.textContent = '';
        return;
      }

      this.debounceTimer = setTimeout(function () {
        self.executeSearch();
      }, 300);
    },

    executeSearch: function () {
      var self = this;
      var cleanQuery = this.query.trim();
      if (!cleanQuery || !window.TmdbClient) return;

      window.TmdbClient.searchMulti(cleanQuery, 1).then(function (res) {
        var results = res && res.results ? res.results : [];
        // Filter: Keep only movie and tv entities with posters
        var filtered = results.filter(function (item) {
          return (item.media_type === 'movie' || item.media_type === 'tv') && item.poster_path;
        });

        self.renderResults(filtered);
        if (self.resultsCount) {
          self.resultsCount.textContent = '(' + filtered.length + ' matches)';
        }
      }).catch(function (err) {
        console.error('[SearchViewController] Multi-search failed:', err);
        self.renderError();
      });
    },

    renderResults: function (items) {
      if (!this.resultsGrid) return;

      if (items.length === 0 && this.query.trim().length > 0) {
        this.resultsGrid.innerHTML = 
          '<div class="search-empty-state" style="grid-column: 1 / -1; padding: 48px; text-align: center; color: rgba(255,255,255,0.6);">' +
            '<p style="font-size: 24px; font-weight: 500;">No titles found for "' + CardFactory.escapeHtml(this.query) + '"</p>' +
            '<p style="font-size: 16px; margin-top: 8px;">Check spelling or try searching for another movie or television series.</p>' +
          '</div>';
        return;
      }

      var fragment = document.createDocumentFragment();
      for (var i = 0; i < items.length; i++) {
        var card = CardFactory.createPosterCard(items[i], 'search-grid', i);
        fragment.appendChild(card);
      }

      this.resultsGrid.innerHTML = '';
      this.resultsGrid.appendChild(fragment);
    },

    renderError: function () {
      if (!this.resultsGrid) return;
      this.resultsGrid.innerHTML = 
        '<div class="search-error-state" style="grid-column: 1 / -1; padding: 48px; text-align: center; color: #ff6b6b;">' +
          '<p style="font-size: 22px;">Search connection failed. Please verify TV network connection.</p>' +
        '</div>';
    }
  };

  global.SearchViewController = SearchViewController;
})(typeof window !== 'undefined' ? window : this);
```

