## 6. View Controller 4: Content Details & Episode Selector Controller (`app/js/views/details.js`)

### 6.1 Responsibilities
1. Fetches full item details via `TmdbClient.getDetails(mediaType, id)` with `append_to_response=credits,recommendations,similar`.
2. Binds high-resolution backdrop image (`w1280` or `original`), title, star rating, release year, runtime, certification badge, genres, and synopsis.
3. Renders action button group:
   - "Play Stream" (`#details-play-btn`, `data-nav="true"`, `data-nav-group="details-actions"`, `data-nav-default="true"`).
   - "Trailer" button.
   - "Add to List" button (toggles local watchlist state).
4. Populates Top Cast horizontal carousel with 80px circular avatars.
5. TV Show Season & Episode Selector:
   - Evaluates `mediaType === 'tv'`.
   - Generates Season Tabs (`Season 1`, `Season 2`, ...).
   - Fetches season episodes via `TmdbClient.getTvSeason(tvId, seasonNumber)`.
   - Renders 16:9 episode still cards with `E{N}` badge, runtime, title, overview, and Play dispatch payload `{ tmdbId, type: 'tv', season, episode }`.
6. For Movies (`mediaType === 'movie'`): Hides the season/episode shelf and renders "More Like This" recommendations.

### 6.2 TV Episode Selector Interaction Flow
```
[ Season 1 (active) ]   [ Season 2 ]   [ Season 3 ]   <── .season-selector-bar
          │
          │ User presses ArrowDown into episode shelf
          ▼
+-------------------------------------------------------------------------------------------------+
| .shelf-rail (16:9 Episode Still Cards - 320px x 180px)                                          |
|                                                                                                 |
| +-------------------------+ +-------------------------+ +-------------------------+             |
| | [ Still Preview ]       | | [ Still Preview ]       | | [ Still Preview ]       |             |
| | E1              62m     | | E2              58m     | | E3              65m     |             |
| | 1. Desert Power         | | 2. The Gathering        | | 3. Water of Life        |  ...        |
| +-------------------------+ +-------------------------+ +-------------------------+             |
+-------------------------------------------------------------------------------------------------+
          │
          │ User presses Enter on Episode Card
          ▼
CinejoyApp.switchView('player', { tmdbId: 196322, type: 'tv', season: 1, episode: 1 })
```

### 6.3 Complete Details Controller Specification
```javascript
(function (global) {
  'use strict';

  var DetailsViewController = {
    initialized: false,
    item: null,
    detailsData: null,
    activeSeason: 1,

    init: function () {
      if (this.initialized) return;
      this.initialized = true;

      this.container = document.getElementById('view-details');
      this.bindActions();
    },

    bindActions: function () {
      var self = this;
      var playBtn = document.getElementById('details-play-btn');
      if (playBtn) {
        playBtn.addEventListener('click', function () {
          if (!self.item) return;
          var payload = {
            tmdbId: self.item.id,
            type: self.item.mediaType || self.item.type || 'movie',
            title: self.item.title || self.item.name
          };

          if (payload.type === 'tv') {
            payload.season = self.activeSeason;
            payload.episode = 1;
          }

          window.CinejoyApp.switchView('player', payload);
        });
      }

      // Delegate Episode Card Clicks
      this.container.addEventListener('click', function (e) {
        var epCard = e.target.closest('.card-episode');
        if (!epCard || !self.item) return;

        var season = parseInt(epCard.getAttribute('data-season') || '1', 10);
        var episode = parseInt(epCard.getAttribute('data-episode') || '1', 10);
        var title = epCard.getAttribute('data-title') || '';

        window.CinejoyApp.switchView('player', {
          tmdbId: self.item.id,
          type: 'tv',
          season: season,
          episode: episode,
          title: self.item.title || self.item.name,
          episodeTitle: title
        });
      });
    },

    activate: function (item) {
      this.init();
      if (item) {
        this.item = item;
        this.loadDetails(item.id, item.mediaType || item.type || 'movie');
      }
    },

    loadDetails: function (id, mediaType) {
      var self = this;
      if (!window.TmdbClient) return;

      window.TmdbClient.getDetails(mediaType, id).then(function (data) {
        self.detailsData = data;
        self.bindHero(data, mediaType);
        self.renderCast(data.credits ? data.credits.cast : []);

        if (mediaType === 'tv') {
          self.renderSeasonSelector(data.number_of_seasons || 1);
          self.loadSeason(id, 1);
        } else {
          self.hideSeasonSelector();
          self.renderRecommendations(data.recommendations ? data.recommendations.results : []);
        }
      }).catch(function (err) {
        console.error('[DetailsViewController] Failed to load details:', err);
      });
    },

    bindHero: function (data, mediaType) {
      var backdropImg = this.container.querySelector('.details-backdrop-img');
      if (backdropImg) {
        backdropImg.src = data.backdrop_path 
          ? window.TmdbClient.getBackdropUrl(data.backdrop_path)
          : 'https://image.tmdb.org/t/p/original/xOMo8BRK7PfcJv9JCnx7s520dQe.jpg';
      }

      var titleEl = document.getElementById('details-title');
      if (titleEl) titleEl.textContent = data.title || data.name || 'Untitled';

      var ratingEl = document.getElementById('details-meta-rating');
      if (ratingEl) {
        ratingEl.textContent = '★ ' + (data.vote_average ? data.vote_average.toFixed(1) : 'NR');
      }

      var yearEl = document.getElementById('details-meta-year');
      if (yearEl) {
        yearEl.textContent = (data.release_date || data.first_air_date || '').slice(0, 4) || '—';
      }

      var synopsisEl = this.container.querySelector('.details-synopsis');
      if (synopsisEl) {
        synopsisEl.textContent = data.overview || 'No synopsis available.';
      }
    },

    renderCast: function (cast) {
      var rail = this.container.querySelector('[data-nav-group="details-cast"]')?.closest('.shelf-rail');
      if (!rail) return;

      var topCast = cast.slice(0, 12);
      var fragment = document.createDocumentFragment();

      for (var i = 0; i < topCast.length; i++) {
        var actor = topCast[i];
        var item = document.createElement('div');
        item.className = 'cast-item';
        item.setAttribute('data-nav', 'true');
        item.setAttribute('data-nav-group', 'details-cast');
        item.setAttribute('data-nav-index', String(i));
        item.setAttribute('tabindex', '-1');

        var avatarUrl = actor.profile_path 
          ? window.TmdbClient.getProfileUrl(actor.profile_path)
          : 'data:image/svg+xml;utf8,<svg ... avatar fallback ... />';

        item.innerHTML = 
          '<div class="cast-avatar"><img src="' + avatarUrl + '" alt="' + CardFactory.escapeHtml(actor.name) + '" loading="lazy"></div>' +
          '<span class="cast-name">' + CardFactory.escapeHtml(actor.name) + '</span>' +
          '<span class="cast-role">' + CardFactory.escapeHtml(actor.character || '') + '</span>';

        fragment.appendChild(item);
      }

      rail.innerHTML = '';
      rail.appendChild(fragment);
    },

    renderSeasonSelector: function (numSeasons) {
      var bar = this.container.querySelector('.season-selector-bar');
      if (!bar) return;
      bar.style.display = 'flex';

      var self = this;
      var fragment = document.createDocumentFragment();

      for (var s = 1; s <= numSeasons; s++) {
        var pill = document.createElement('button');
        pill.className = 'season-pill' + (s === 1 ? ' active' : '');
        pill.setAttribute('data-nav', 'true');
        pill.setAttribute('data-nav-group', 'season-pills');
        pill.setAttribute('data-season', String(s));
        pill.textContent = 'Season ' + s;

        pill.addEventListener('click', function () {
          var targetSeason = parseInt(this.getAttribute('data-season'), 10);
          self.activeSeason = targetSeason;

          bar.querySelectorAll('.season-pill').forEach(function (p) { p.classList.remove('active'); });
          this.classList.add('active');

          if (self.item) {
            self.loadSeason(self.item.id, targetSeason);
          }
        });

        fragment.appendChild(pill);
      }

      bar.innerHTML = '';
      bar.appendChild(fragment);
    },

    loadSeason: function (tvId, seasonNumber) {
      var self = this;
      if (!window.TmdbClient) return;

      window.TmdbClient.getTvSeason(tvId, seasonNumber).then(function (seasonData) {
        var episodes = seasonData && seasonData.episodes ? seasonData.episodes : [];
        self.renderEpisodes(episodes, seasonNumber);
      }).catch(function (err) {
        console.error('[DetailsViewController] Failed to load season:', err);
      });
    },

    renderEpisodes: function (episodes, seasonNumber) {
      var rail = this.container.querySelector('[data-nav-group="details-episodes"]')?.closest('.shelf-rail');
      if (!rail) return;

      var fragment = document.createDocumentFragment();
      for (var i = 0; i < episodes.length; i++) {
        var card = CardFactory.createEpisodeCard(episodes[i], seasonNumber, i);
        fragment.appendChild(card);
      }

      rail.innerHTML = '';
      rail.appendChild(fragment);
    },

    hideSeasonSelector: function () {
      var bar = this.container.querySelector('.season-selector-bar');
      if (bar) bar.style.display = 'none';

      var epShelf = this.container.querySelector('[data-nav-group="details-episodes"]')?.closest('.content-shelf');
      if (epShelf) epShelf.style.display = 'none';
    },

    renderRecommendations: function (items) {
      // Replaces episode shelf with recommended titles for movies
      var recShelf = this.container.querySelector('.details-recommendations-shelf');
      if (!recShelf) return;
      recShelf.style.display = 'block';

      var rail = recShelf.querySelector('.shelf-rail');
      if (!rail) return;

      var fragment = document.createDocumentFragment();
      var maxItems = Math.min(items.length, 12);
      for (var i = 0; i < maxItems; i++) {
        var card = CardFactory.createPosterCard(items[i], 'details-recommendations', i, { mediaType: 'movie' });
        fragment.appendChild(card);
      }
      rail.innerHTML = '';
      rail.appendChild(fragment);
    }
  };

  global.DetailsViewController = DetailsViewController;
})(typeof window !== 'undefined' ? window : this);
```

